// minerpg: the Ascension tab's gate (pack 1.8.0).
// Design: docs/superpowers/specs/2026-11-11-minerpg-ascension-design.md. The tab (Pufferfish category
// minerpg:ascension) is generated by pack/tools/gen_ascension.py; its rules are in startup_scripts/minerpg_ascension.js
// and its effects in server_scripts/minerpg_ascension_effects.js.
//
// The tab opens once a player has an Ascension point (only bosses give them: quest rewards, source minerpg:bosses)
// and their main class has Fates (rules.json "wave"). Players of other classes keep their points in the locked tab
// until their class's wave ships.

const $AGSkillsAPI = Java.loadClass('net.puffish.skillsmod.api.SkillsAPI')
const $AGRL = Java.loadClass('net.minecraft.resources.ResourceLocation')

const AG_ID = 'minerpg:ascension'
const AG_MAIN_ID = 'skill_tree_rpgs:class_skills'
const AG_RULES = JsonIO.read('kubejs/ascension/rules.json')
const AG_SIDE_RULES = JsonIO.read('kubejs/side_class/rules.json')

function agCategory(id) {
  var category = $AGSkillsAPI.getCategory($AGRL.parse(id))
  return category.isPresent() ? category.get() : null
}

function agMainClass(player) {
  var main = agCategory(AG_MAIN_ID)
  if (main == null || AG_SIDE_RULES == null) return null
  var found = null
  main.streamUnlockedSkills(player).forEach(skill => {
    var cls = AG_SIDE_RULES.main_roots[String(skill.getId())]
    if (cls) found = String(cls)
  })
  return found
}

// Opens the tab when the player has a point and a wave class. Never locks it again.
function ascUpdateGate(player) {
  var asc = agCategory(AG_ID)
  if (asc == null || AG_RULES == null || asc.isUnlocked(player)) return
  if (asc.getPointsTotal(player) < 1) return
  var cls = agMainClass(player)
  var inWave = false
  AG_RULES.wave.forEach(w => { if (String(w) == cls) inWave = true })
  if (inWave) asc.unlock(player)
}

// Pack 1.8.0, once per player: the class tree lost its Mastery tier and its four boss points (22 -> 18 points), and
// those boss points became Ascension points. Players who already earned them get them in the new tab, and every class
// tree is reset for free so nobody keeps more points spent than the tree now has.
const AG_MIGRATED = 'minerpg_ascension_migrated_1_8'
const $AGComponent = Java.loadClass('net.minecraft.network.chat.Component')
const $AGFormat = Java.loadClass('net.minecraft.ChatFormatting')

function ascMigrate(player) {
  var data = player.getPersistentData()
  if (data.getBoolean(AG_MIGRATED)) return
  data.putBoolean(AG_MIGRATED, true)
  var main = agCategory(AG_MAIN_ID)
  var asc = agCategory(AG_ID)
  if (main == null || asc == null) return
  var bosses = $AGRL.parse('minerpg:bosses')
  var moved = main.getPoints(player, bosses)
  if (moved > 0) {
    main.setPoints(player, bosses, 0)
    asc.addPoints(player, bosses, moved)
  }
  var reset = main.getSpentPoints(player) > 0
  if (reset) main.resetSkills(player)
  if (moved == 0 && !reset) return
  // withStyle is overloaded (formatting / style / operator); Rhino needs the one named.
  player.tell($AGComponent.literal('Ascension has arrived: ' + (moved > 0 ? 'your ' + moved + ' boss talent point'
    + (moved > 1 ? 's' : '') + ' moved to the new Ascension tab, and ' : '') + 'your class talents were reset for free '
    + '(the class tree now has 18 points). See "Ascension and Fates" in the handbook.')
    ['withStyle(net.minecraft.ChatFormatting)']($AGFormat.GOLD))
}

PlayerEvents.loggedIn(event => {
  ascMigrate(event.player)
  ascUpdateGate(event.player)
})

var agTicks = 0
ServerEvents.tick(event => {
  agTicks++
  if (agTicks % 100 != 0) return
  event.server.getPlayerList().getPlayers().forEach(player => ascUpdateGate(player))
})
